(()=>{'use strict';
const C=window.SKILLBRIDGE_CONTENT,challenges=C.challenges,paths=C.paths,byId=Object.fromEntries(challenges.map(x=>[x.id,x]));
const SKEY='skillbridge.studio.pro.v1';let state;try{state=JSON.parse(localStorage.getItem(SKEY)||'{}')||{}}catch{state={}}
state={name:'Guest learner',role:'Product Analyst',theme:'light',path:'product',progress:{},drafts:{},saved:[],feedback:[],activity:[],scan:null,job:'',resume:'',...state};if(!state.progress)state.progress={};if(!state.drafts)state.drafts={};
let page='dashboard',labId='ab-hotel',labTab='brief',topic='All topics',difficulty='Any level',search='',loading=false,geminiConnected=false,teamCode='',cloudConfigured=false,coachResponse='',lastError='',modalContent='',mobileMenu=false;
const catIcon={'Experimentation':'flask','SQL & Data':'database','Python & Pandas':'code','Statistics':'chart','Product Analytics':'target','Finance & Pricing':'wallet','Marketing':'megaphone','Operations':'layers','Machine Learning':'brain','Strategy':'compass','Data Storytelling':'pie'};
const svgPaths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',book:'<path d="M4 19.5V5a2 2 0 0 1 2-2h13v17H6a2 2 0 0 0 0 4"/><path d="M6 19.5a2 2 0 0 0 0 4h13"/>',award:'<circle cx="12" cy="8" r="6"/><path d="m8.2 13.8-1.2 8 5-3 5 3-1.2-8"/>',chart:'<path d="M3 3v18h18"/><path d="m7 15 4-5 4 3 5-7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3l-.5.2V22h-4v-2.4l-.5-.2a1.7 1.7 0 0 0-1.9.3l-.1.1-2.8-2.8.1-.1a1.7 1.7 0 0 0 .3-1.9l-.2-.5H3v-4h2.4l.2-.5a1.7 1.7 0 0 0-.3-1.9l-.1-.1 2.8-2.8.1.1a1.7 1.7 0 0 0 1.9.3l.5-.2V3h4v2.4l.5.2a1.7 1.7 0 0 0 1.9-.3l.1-.1 2.8 2.8-.1.1a1.7 1.7 0 0 0-.3 1.9l.2.5H22v4h-2.4z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/>',moon:'<path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/>',chevron:'<path d="m9 18 6-6-6-6"/>',arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m4 12 5 5L20 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',spark:'<path d="m12 3 2.2 6.8L21 12l-6.8 2.2L12 21l-2.2-6.8L3 12l6.8-2.2z"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 13h18"/>',database:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 1.7 4 3 9 3s9-1.3 9-3V5M3 12c0 1.7 4 3 9 3s9-1.3 9-3"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5M14 4l-4 16"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18m-5 6h2"/>',megaphone:'<path d="M3 11v3a2 2 0 0 0 2 2h3l3 5h3l-3-6 10-5V4L8 9H5a2 2 0 0 0-2 2z"/>',layers:'<path d="m12 2 9 5-9 5-9-5 9-5Zm-9 10 9 5 9-5M3 17l9 5 9-5"/>',brain:'<path d="M12 18V6a4 4 0 0 0-7-2 4 4 0 0 0-2 6 4 4 0 0 0 1 7 4 4 0 0 0 8 1Zm0 0V6a4 4 0 0 1 7-2 4 4 0 0 1 2 6 4 4 0 0 1-1 7 4 4 0 0 1-8 1Z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 6-5 2 2-5z"/>',pie:'<path d="M12 3v9h9A9 9 0 1 1 12 3Z"/><path d="M16 3a9 9 0 0 1 5 5h-5z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',upload:'<path d="M12 16V4m-4 4 4-4 4 4M4 17v4h16v-4"/>',heart:'<path d="M20 5a5 5 0 0 0-7 0l-1 1-1-1a5 5 0 0 0-7 7l8 8 8-8a5 5 0 0 0 0-7Z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',x:'<path d="M5 5l14 14M19 5 5 19"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',star:'<path d="m12 2 3.1 6.3 7 1-5 4.9 1.2 6.9L12 18l-6.3 3.1 1.2-6.9-5-4.9 7-1z"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v5h5"/>',refresh:'<path d="M3 12a9 9 0 0 1 15-6l3 3M21 3v6h-6M21 12a9 9 0 0 1-15 6l-3-3M3 21v-6h6"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v7m4-7v7"/>',filter:'<path d="M3 5h18l-7 8v6l-4 2v-8z"/>',trending:'<path d="M3 17l6-6 4 4 8-8M15 7h6v6"/>',shield:'<path d="M12 2 4 5v6c0 5 3 8 8 11 5-3 8-6 8-11V5z"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>'};
function ico(n,size=18){return `<svg class="ic" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svgPaths[n]||svgPaths.spark}</svg>`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function save(){try{localStorage.setItem(SKEY,JSON.stringify(state))}catch{toast('Browser storage is full; export your progress')}}
function toast(m){const div=document.createElement('div');div.className='toast';div.innerHTML=ico('info',16)+`<span>${esc(m)}</span>`;document.querySelector('.toast-stack')?.append(div);setTimeout(()=>div.remove(),4200)}
const prog=()=>Object.values(state.progress||{});function completed(){return prog().filter(x=>x.completed)}function totalMinutes(){return completed().reduce((a,p)=>a+(byId[p.id]?.minutes||0),0)}function avgScore(){const c=completed();return c.length?Math.round(c.reduce((s,p)=>s+(p.bestScore||0),0)/c.length):0}
function modeLabel(){return geminiConnected?'Gemini access verified':window.SkillBridgeLocal?.ready()?'On-device AI ready':'Practice mode'}
function updateTheme(){document.body.classList.toggle('dark',state.theme==='dark')}
const navs=[['dashboard','Overview','home'],['explore','Challenge library','grid'],['paths','Learning paths','target'],['scan','Skill scan','spark'],['portfolio','Portfolio','award'],['insights','My progress','chart'],['testing','User feedback','heart'],['settings','Settings','settings']];
function shell(content){const current=navs.find(n=>n[0]===page);const primary=navs.slice(0,6);const secondary=navs.slice(6);return `<div class="shell glass-shell"><header class="topbar glass-topbar"><div class="nav-shell"><button class="brand brand-button" data-page="dashboard" aria-label="SkillBridge Home"><span class="brand-mark">${ico('spark',23)}</span><span class="brand-word">skill<span>bridge</span><sup>®</sup></span></button><nav class="top-nav" aria-label="Main navigation">${primary.map(([id,label,ic])=>`<button class="top-nav-link ${id===page?'active':''}" data-page="${id}">${esc(id==='dashboard'?'Home':id==='explore'?'Explore':id==='paths'?'Paths':id==='scan'?'Skill scan':id==='portfolio'?'Portfolio':'Progress')}</button>`).join('')}</nav><div class="top-actions"><span class="mode-pill ${geminiConnected||window.SkillBridgeLocal?.ready()?'live':''}"><span class="mode-dot"></span>${esc(modeLabel())}</span><button class="icon-btn utility-button" data-action="quicksearch" title="Find a challenge" aria-label="Find a challenge">${ico('search',19)}</button><button class="icon-btn utility-button" data-action="theme" title="Change theme" aria-label="Switch theme">${ico(state.theme==='dark'?'sun':'moon',19)}</button><button class="avatar avatar-action" data-page="settings" title="Settings" aria-label="Open settings">${ico('settings',19)}</button><button class="icon-btn mobile-menu" data-action="menu" title="Menu" aria-label="Toggle navigation" aria-expanded="${mobileMenu?'true':'false'}">${ico(mobileMenu?'x':'menu',21)}</button></div></div>${mobileMenu?`<nav class="mobile-nav-panel" aria-label="Mobile navigation">${navs.map(([id,label,ic])=>`<button class="mobile-nav-item ${id===page?'active':''}" data-page="${id}">${ico(ic,18)}${esc(id==='dashboard'?'Home':label)}${ico('arrow',15)}</button>`).join('')}</nav>`:''}</header><main class="app-main"><div class="page">${content}</div><footer class="site-footer"><div class="footer-brand"><span class="brand-mark">${ico('spark',18)}</span><strong>skillbridge</strong></div><span>Big skills. Real practice. Your story.</span><div class="footer-links"><button data-page="testing">Give feedback</button><button data-page="settings">Settings</button><span>USC MSBA student prototype</span></div></footer></main></div><div id="modal-root"></div><div class="toast-stack" aria-live="polite"></div>`}
function section(title,linkLabel='',target='explore'){return `<div class="section-header"><h2 class="section-title">${esc(title)}</h2>${linkLabel?`<button class="section-link" data-page="${target}">${esc(linkLabel)} ${ico('arrow',14)}</button>`:''}</div>`}
function card(d){const p=state.progress[d.id],done=p?.completed,saved=state.saved.includes(d.id),color={'Experimentation':'peach','SQL & Data':'lilac','Python & Pandas':'mint','Statistics':'sky','Product Analytics':'lemon','Finance & Pricing':'peach','Marketing':'lilac','Operations':'sky','Machine Learning':'mint','Strategy':'lemon','Data Storytelling':'lilac'}[d.category]||'lilac';return `<article class="panel challenge-card bubbly-card"><div class="case-glow ${color}"></div><div class="card-top"><span class="card-symbol ${color}">${ico(catIcon[d.category]||'book',22)}</span><button class="icon-btn bookmark-icon" data-favorite="${d.id}" title="${saved?'Remove bookmark':'Bookmark'}" aria-label="${saved?'Remove bookmark for':'Bookmark'} ${esc(d.title)}">${ico(saved?'star':'heart',18)}</button></div><div class="card-category">${esc(d.category)} <span class="smallbullet">•</span> ${esc(d.level)}</div><h3>${esc(d.title)}</h3><p>${esc(d.brief)}</p><div class="card-bottom"><span>${ico('clock',14)} ${d.minutes} min</span><button class="round-arrow" data-case="${d.id}" title="${done?'Review':'Start'} ${esc(d.title)}" aria-label="${done?'Review':'Start'} ${esc(d.title)}">${ico(done?'check':'arrow',20)}</button></div>${done?'<span class="project-badge case-done">'+ico('check',11)+' Completed</span>':''}</article>`}
function empty(title,message,button='Explore challenges',action='explore'){return `<div class="panel empty"><div class="empty-icon">${ico('spark',26)}</div><h3>${esc(title)}</h3><p>${esc(message)}</p><button class="btn primary" data-page="${action}">${esc(button)} ${ico('arrow',15)}</button></div>`}
function dashboard(){const c=completed(),path=paths.find(p=>p.id===state.path)||paths[0],pathDone=path.ids.filter(id=>state.progress[id]?.completed).length,recs=(path.ids.filter(x=>!state.progress[x]?.completed).map(x=>byId[x])).concat(challenges.filter(d=>!state.progress[d.id]?.completed)).filter((v,i,a)=>a.findIndex(o=>o.id===v.id)===i).slice(0,3);const categories=[...new Set(challenges.map(d=>d.category))];let topicItems=[['Experimentation','peach','flask'],['SQL & Data','mint','grid'],['Product Analytics','lilac','chart'],['Finance & Pricing','lemon','target'],['Python & Pandas','sky','book'],['Machine Learning','pink','spark']];return `<div class="home-page"><section class="hero-glass"><div class="hero-noise"></div><div class="hero-main"><div class="hero-kicker"><span class="kicker-star">✳</span> THE SKILL-BUILDING PLAYGROUND <span class="kicker-line"></span> FOR NEXT-GEN ANALYSTS</div><h1>Don't just learn it.<br><span class="headline-swish">Show what you can do<span class="headline-period">.</span></span></h1><p class="hero-lead">Turn the skills you want into projects you're proud of. Find your gap, crack real-world style business challenges, and build a portfolio that actually says something.</p><div class="hero-buttons"><button class="btn primary cta-xl" data-page="scan">Find my skill gap ${ico('arrow',17)}</button><button class="btn glass-cta cta-xl" data-page="explore">Explore the playground ${ico('arrow',17)}</button></div><div class="hero-proof"><div class="proof-dots"><i></i><i></i><i></i></div><span>33 business challenges <span class="sepdot">✦</span> 11 topics <span class="sepdot">✦</span> 100% hands-on</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-1"></div><div class="orbit orbit-2"></div><div class="orbit orbit-3"></div><div class="float-badge bubble-star">✳</div><div class="float-badge bubble-chart">${ico('chart',34)}</div><div class="float-badge bubble-trophy">${ico('award',30)}</div><div class="glass-card skill-paper"><div class="paper-top"><span class="paper-icon">${ico('spark',18)}</span><span>YOUR NEXT LEVEL</span><span class="paper-dots">•••</span></div><div class="paper-title">Product Analyst</div><div class="paper-subtitle">One challenge closer.</div><div class="paper-divider"></div><div class="paper-row"><span class="tiny-symbol purple-sym">${ico('grid',17)}</span><span>SQL & analytics</span><span class="tiny-check">${ico('check',13)}</span></div><div class="paper-row"><span class="tiny-symbol mint-sym">${ico('chart',17)}</span><span>A/B experiments</span><span class="paper-next">Up next ${ico('arrow',12)}</span></div><div class="paper-footer"><span class="green-flare">✳</span> Your story is in progress</div></div><div class="art-pill art-pill-left">${ico('spark',15)} LEARN BY DOING</div><div class="art-pill art-pill-right">BUILD YOUR PROOF ↗</div></div><div class="hero-floating-blob"></div></section><div class="marquee-band"><div><span>LEARN</span> <span class="marquee-symbol">✳</span> <span>PRACTICE</span> <span class="marquee-symbol">✦</span> <span>PROVE IT</span> <span class="marquee-symbol">✳</span> <span>REPEAT</span> <span class="marquee-symbol">✦</span> <span>LEARN</span></div></div><section class="landing-section"><div class="landing-heading"><div><p class="mini-kicker">YOU'RE IN THE DRIVER'S SEAT</p><h2>What are we <em>building</em> today?</h2></div><button class="pill-link" data-page="explore">All 33 challenges ${ico('arrow',15)}</button></div><div class="topic-bubbles">${topicItems.map(([t,col,ic])=>`<button data-topic="${esc(t)}" class="topic-bubble ${col}"><span class="topic-bubble-icon">${ico(ic,23)}</span><span>${esc(t)}</span><span class="bubble-arrow">↗</span></button>`).join('')}</div></section><section class="landing-section"><div class="landing-heading"><div><p class="mini-kicker">NO BORING THEORY-ONLY STUFF</p><h2>Start with something <em>real.</em></h2><p>Short, meaningful cases that make your brain do the heavy lifting.</p></div><button class="pill-link" data-page="explore">See the collection ${ico('arrow',16)}</button></div><div class="grid g3 featured-cases">${recs.map(card).join('')}</div></section><section class="landing-section"><div class="journey-section"><div class="journey-head"><div><p class="mini-kicker">THE WHOLE IDEA</p><h2>Skills don't build <em>themselves.</em><br>But we make it fun.</h2></div><span class="journey-spark">✳</span></div><div class="journey-grid"><button class="journey-step" data-page="scan"><span class="journey-num">01 / FIND IT</span><span class="journey-icon peach">${ico('search',27)}</span><strong>Spot your gap.</strong><span>Compare a target role with the work you've done.</span><i>${ico('arrow',19)}</i></button><button class="journey-step" data-page="explore"><span class="journey-num">02 / TRY IT</span><span class="journey-icon lemon">${ico('book',27)}</span><strong>Do the challenge.</strong><span>Get your hands on a business problem and dataset.</span><i>${ico('arrow',19)}</i></button><button class="journey-step" data-page="paths"><span class="journey-num">03 / GROW IT</span><span class="journey-icon lilac">${ico('spark',27)}</span><strong>Level up.</strong><span>Get checks, thoughtful feedback, and a clear next step.</span><i>${ico('arrow',19)}</i></button><button class="journey-step" data-page="portfolio"><span class="journey-num">04 / SHOW IT</span><span class="journey-icon mint">${ico('award',27)}</span><strong>Make it yours.</strong><span>Build a portfolio case from the work you actually did.</span><i>${ico('arrow',19)}</i></button></div></div></section><section class="landing-section split-feature"><div class="feature-text"><p class="mini-kicker">YOUR MOMENTUM MATTERS</p><h2>Your own pace.<br><em>Your own path.</em></h2><p>Follow a career-focused practice path, save what interests you, and watch real progress stack up—one case at a time.</p><div class="feature-actions"><button class="btn primary cta-xl" data-page="paths">Explore learning paths ${ico('arrow',17)}</button></div></div><div class="glass-progress"><div class="progress-kicker">CURRENT PATH <span>✳</span></div><h3>${esc(path.title)}</h3><p>${esc(path.desc)}</p><div class="progress-line"><span>${pathDone} of ${path.ids.length} cases completed</span><b>${Math.round(pathDone/path.ids.length*100)}%</b></div><div class="meter"><span style="width:${pathDone/path.ids.length*100}%"></span></div><div class="progress-mini-stats"><span><strong>${c.length}</strong> Cases done</span><span><strong>${new Set(c.map(p=>byId[p.id]?.category)).size}</strong> Topics</span><span><strong>${totalMinutes()}</strong> Minutes</span></div><button class="glassy-link" data-page="insights">View my progress ${ico('arrow',17)}</button></div></section><section class="bottom-cta"><span class="bottom-asterisk">✳</span><p>Ready to make some moves?</p><h2>You've got potential.<br><em>Let's make it visible.</em></h2><button class="btn white cta-xl" data-page="explore">Let's practice ${ico('arrow',18)}</button><span class="bottom-bubble-small">✦</span></section></div>`}
function exploreGrid(){let found=challenges.filter(d=>(topic==='All topics'||d.category===topic)&&(difficulty==='Any level'||d.level===difficulty)&&(`${d.title} ${d.brief} ${d.skills.join(' ')} ${d.category}`.toLowerCase().includes(search.toLowerCase())));return `<div class="grid g3">${found.map(card).join('')}</div>${!found.length?empty('No matching cases','Try a different topic, level or search term.'):''}`}
function explore(){const cats=['All topics',...new Set(challenges.map(d=>d.category))];return `<div class="section-header"><div><div class="eyebrow">PRACTICE LIBRARY</div><h1>Explore the case collection.</h1><p class="subtext">${challenges.length} hands-on business challenges · ${cats.length-1} topics · carefully constructed synthetic datasets.</p></div><span class="mode-pill">${ico('book',14)} Every case is interactive</span></div><div class="toolbar"><label class="search-wrap">${ico('search',16)}<input class="search-input" id="case-search" placeholder="Search cases, topics, or skills…" value="${esc(search)}" aria-label="Search case library"/></label><select id="case-level" aria-label="Difficulty">${['Any level','Beginner','Intermediate','Advanced'].map(v=>`<option ${difficulty===v?'selected':''}>${v}</option>`).join('')}</select><button class="btn secondary" data-action="clearfilters">${ico('refresh',15)} Reset</button></div><div class="tabs">${cats.map(t=>`<button class="tab ${topic===t?'active':''}" data-topic="${esc(t)}">${esc(t)}</button>`).join('')}</div><div id="explore-grid">${exploreGrid()}</div><div class="note" style="margin-top:25px">${ico('info',15)} All cases use synthetic scenarios and data. Numeric and choice questions are checked against answer keys; written recommendations receive advisory feedback rather than a certification.</div>`}
function pathsView(){return `<div class="section-header"><div><div class="eyebrow">GUIDED PRACTICE</div><h1>Your next six moves.</h1><p class="subtext">Structured learning paths that turn one career direction into a sequence of finished cases.</p></div></div><div class="grid g3">${paths.map(p=>{const cnt=p.ids.filter(id=>state.progress[id]?.completed).length;return `<div class="panel path-card ${p.id===state.path?'selected':''}"><span class="card-symbol">${ico(p.icon,22)}</span><h3>${esc(p.title)}</h3><p>${esc(p.desc)}</p><div class="path-meta"><span>${cnt}/${p.ids.length} cases</span><span>${Math.round(cnt/p.ids.length*100)}%</span></div><div class="meter"><span style="width:${cnt/p.ids.length*100}%"></span></div><button class="btn ${p.id===state.path?'secondary':'primary'}" style="margin-top:15px" data-path="${p.id}">${p.id===state.path?'Continue path':'Set as my path'} ${ico('arrow',15)}</button></div>`}).join('')}</div><div id="path-detail">${pathDetail()}</div>`}
function pathDetail(){const p=paths.find(o=>o.id===state.path)||paths[0];return `<div class="section-space">${section(p.title)}</div><div class="grid g3">${p.ids.map(id=>byId[id]).map(card).join('')}</div>`}

const sourceLabels={summary:'Summary',resumePdf:'Resume PDF',linkedin:'LinkedIn'};
const sourceDraft={linkedinUrl:'',linkedinText:'',profileNotice:'',pdfs:{},useSummary:true,busy:false};
function captureSources(){if(page!=='scan')return;const ids={'job-input':'job','resume-input':'resume','role-input':'role'};for(const [id,key] of Object.entries(ids)){const el=document.getElementById(id);if(el)state[key]=el.value;}const url=document.getElementById('linkedin-url'),text=document.getElementById('linkedin-text'),toggle=document.getElementById('use-summary');if(url)sourceDraft.linkedinUrl=url.value;if(text)sourceDraft.linkedinText=text.value;if(toggle)sourceDraft.useSummary=toggle.checked;}
function sourceIds(){return [sourceDraft.useSummary&&state.resume.trim()?'summary':null,sourceDraft.pdfs.resumePdf?'resumePdf':null,sourceDraft.linkedinText.trim()||sourceDraft.pdfs.linkedin?'linkedin':null].filter(Boolean);}
function sourceMeter(){const ids=sourceIds();return `<div class="source-meter"><div><strong id="source-count">${ids.length} / 3 sources ready</strong><span>One is enough. Combine sources for fuller context.</span></div><div class="source-chips">${Object.entries(sourceLabels).map(([id,label])=>`<span data-source-chip="${id}" class="${ids.includes(id)?'ready':''}">${ico(ids.includes(id)?'check':'plus',12)} ${label}</span>`).join('')}</div></div>`;}
function updateSourceMeter(){const ids=sourceIds(),count=document.getElementById('source-count');if(count)count.textContent=ids.length+' / 3 sources ready';document.querySelectorAll('[data-source-chip]').forEach(e=>{const id=e.dataset.sourceChip,ready=ids.includes(id);e.classList.toggle('ready',ready);e.innerHTML=ico(ready?'check':'plus',12)+' '+esc(sourceLabels[id]);});}
function pdfPicker(id,label){const doc=sourceDraft.pdfs[id];return `<div class="pdf-picker"><label class="field-label" for="${id}-file">${label}</label><input type="file" id="${id}-file" accept="application/pdf,.pdf" ${loading||sourceDraft.busy?'disabled':''}><p class="field-help">${doc?`${esc(doc.name)} · ready for Gemini review`:'PDF up to 2 MB; 3 MB combined. Choose an unlocked copy.'}</p>${doc?`<button class="btn small secondary" data-action="remove-pdf" data-source="${id}">Remove PDF</button>`:''}</div>`;}
function extraSourceInputs(){return `<div class="source-divider"></div>${pdfPicker('resumePdf','Resume PDF (optional)')}<div class="source-divider"></div><div class="form-group"><label class="field-label" for="linkedin-url">LinkedIn profile link (optional)</label><div class="source-url-row"><input class="text-input" type="url" id="linkedin-url" value="${esc(sourceDraft.linkedinUrl)}" placeholder="https://www.linkedin.com/in/your-profile/" maxlength="300"><button class="btn secondary" data-action="import-linkedin" ${loading||sourceDraft.busy?'disabled':''}>Try public import</button></div><p class="field-help">LinkedIn may block imports. A link alone does not count as reviewed evidence.</p></div>${sourceDraft.profileNotice?`<div class="note source-notice" role="status">${esc(sourceDraft.profileNotice)}</div>`:''}<details class="source-details" ${sourceDraft.linkedinText||sourceDraft.profileNotice?'open':''}><summary>Paste LinkedIn sections or upload a profile PDF</summary><label class="field-label" for="linkedin-text">LinkedIn About, Experience, Education & Skills</label><textarea id="linkedin-text" class="text-area" maxlength="16000" placeholder="Paste your LinkedIn profile content here if the public link cannot be read…">${esc(sourceDraft.linkedinText)}</textarea><p class="field-help">Review imported text for accuracy. You can also paste profile text without adding a URL.</p>${pdfPicker('linkedin','LinkedIn profile PDF (optional)')}</details><div class="note source-privacy">Selected PDFs and profile text are sent to Gemini only when you analyze. Original PDFs and full LinkedIn text stay in this tab. Reviewed excerpts are saved with your results and progress backups. Remove contact details you do not want reviewed.</div>`;}
function sourceReview(){const r=state.scan;if(!r?.reviewedSources)return '';return `<section class="source-review"><strong>${r.reviewedSources.length} / 3 sources reviewed</strong><div class="source-chips">${r.reviewedSources.map(id=>`<span class="ready">${ico('check',12)} ${esc(sourceLabels[id]||id)}</span>`).join('')}</div><p>More context can reveal missing details and inconsistencies; it does not prove that a claim is true.</p>${(r.sourceWarnings||[]).map(w=>`<div class="note">${esc(w)}</div>`).join('')}${r.inconsistencies?.length?`<details open><summary>Claims to verify across sources</summary><ul>${r.inconsistencies.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></details>`:''}</section>`;}
function evidenceCitations(s){return s.evidence?.length?`<div class="evidence-citations">${s.evidence.map(e=>`<details><summary>${esc(sourceLabels[e.source]||e.source)} evidence</summary><blockquote>${esc(e.quote)}</blockquote></details>`).join('')}</div>`:'';}
async function selectPdf(id,file){captureSources();if(!file)return;if(file.size>2*1024*1024){toast('Choose a PDF under 2 MB.');return;}if(Object.entries(sourceDraft.pdfs).filter(([key])=>key!==id).reduce((n,[,d])=>n+d.size,0)+file.size>3*1024*1024){toast('Keep the combined PDFs under 3 MB.');return;}sourceDraft.busy=true;render();try{const bytes=new Uint8Array(await file.arrayBuffer());if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-')throw new Error('This file is not a PDF.');let binary='';for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));sourceDraft.pdfs[id]={id,name:file.name.slice(0,100),size:file.size,data:btoa(binary)};if(id==='resumePdf'&&state.resume.trim()){sourceDraft.useSummary=false;sourceDraft.profileNotice='Your existing summary is excluded to avoid mixing old sample text with this PDF. Select “Include summary” if you want both reviewed.';}toast('PDF selected. Choose Analyze evidence to review it.');}catch(e){toast(e.message||'Could not open this PDF.');}finally{sourceDraft.busy=false;render();}}
async function importProfile(){captureSources();if(!sourceDraft.linkedinUrl.trim()){sourceDraft.profileNotice='Add a LinkedIn profile link, or paste profile text below.';render();return false;}if(!geminiConnected){sourceDraft.profileNotice='Connect Gemini in Settings to try a public import. You can paste your profile text below at any time.';render();return false;}loading=true;render();try{const r=await api('linkedin',{url:sourceDraft.linkedinUrl.trim()});sourceDraft.linkedinUrl=r.url;sourceDraft.linkedinText=r.text;sourceDraft.profileNotice='Public text imported. Review it below before analyzing; it may be incomplete.';return true;}catch(e){sourceDraft.profileNotice=e.message||'LinkedIn import unavailable. Paste your profile text or upload a profile PDF.';return false;}finally{loading=false;render();}}

function evidenceLevel(s){const score=[0,25,50,75,100].includes(s.evidenceScore)?s.evidenceScore:null;const levels={0:['red','No evidence yet'],25:['coral','Mentioned'],50:['amber','Learning evidence'],75:['lime','Applied evidence'],100:['green','Outcome-backed']};return score===null?{score:null,tone:'pending',label:'Rescan for level'}:{score,tone:levels[score][0],label:levels[score][1]};}
function evidenceNode(s,i){const e=evidenceLevel(s),known=e.score!==null;return `<article class="evidence-node evidence-${e.tone}"><span class="evidence-orb" aria-hidden="true">${known&&e.score>=75?ico('check',18):ico('spark',18)}</span><div class="evidence-node-body"><div class="evidence-node-head"><h4>${esc(s.name)}</h4><span class="evidence-level">${e.label}</span></div><p>${esc(s.reason||'Run a fresh scan to assess the evidence in your resume.')}</p><div class="evidence-track" role="progressbar" aria-label="${esc(s.name)} source evidence" aria-valuemin="0" aria-valuemax="100" ${known?`aria-valuenow="${e.score}"`:''} aria-valuetext="${e.label}"><span style="width:${known?e.score:0}%"></span></div>${evidenceCitations(s)}<div class="evidence-scale"><span>${known?`Level ${e.score/25} / 4`:'Run a new scan for a graded level'}</span><span>${known&&e.score===100?'Proof documented':known&&e.score>=75?'Add a measured outcome':known&&e.score>=25?'Build a concrete example':'Start with a practice project'}</span></div></div></article>`;}
function scanPage(){let prev=state.scan,skills=prev?.skills||[], found=skills.filter(s=>s.found),missing=skills.filter(s=>!s.found);return `<div class="section-header"><div><div class="eyebrow">CAREER INTELLIGENCE</div><h1>Find your next evidence gap.</h1><p class="subtext">Use a resume PDF, LinkedIn profile content, a quick summary, or any combination. Compare your evidence with a target job—not your personal worth.</p></div></div>${sourceMeter()}<div class="grid g2"><div class="panel panel-pad"><div class="form-group"><label class="field-label" for="role-input">Target role</label><input class="text-input" id="role-input" value="${esc(state.role)}" maxlength="120" placeholder="e.g. Product Analyst Intern"></div><div class="form-group"><label class="field-label" for="job-input">Job description</label><textarea id="job-input" class="text-area large" placeholder="Paste requirements from a job posting…">${esc(state.job)}</textarea></div><div class="form-group"><label class="field-label" for="resume-input">Quick summary (optional)</label><label class="source-toggle"><input type="checkbox" id="use-summary" ${sourceDraft.useSummary?'checked':''}> Include summary in this review</label><textarea id="resume-input" class="text-area large" placeholder="Paste selected experience bullets. Remove personal contact details first…">${esc(state.resume)}</textarea><p class="field-help">The original summary option still works on its own. Add specific actions and results.</p></div>${extraSourceInputs()}<div class="inline-actions"><button class="btn primary" data-action="scan" ${loading||sourceDraft.busy?'disabled':''}>${ico('spark',16)} ${loading?'Analyzing…':'Analyze evidence'}</button><button class="btn secondary" data-action="sample-scan">${ico('file',15)} Load sample</button></div></div><div class="panel panel-pad">${skills.length?`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><h3 style="font:800 18px Manrope;margin:0">Your evidence map</h3><span class="tag purple">${esc(prev.method||'Practice scan')}</span></div>${sourceReview()}<p class="evidence-intro">Your skill upgrade path. Red → amber → green as your sources show stronger evidence.</p><div class="grid g2" style="margin-bottom:12px"><div class="accentbox"><strong style="display:block;font-size:22px">${found.length}</strong><span class="smalltext">Requirements evidenced</span></div><div class="note attention"><strong style="display:block;font-size:22px">${missing.length}</strong><span class="smalltext">Evidence gaps</span></div></div><div class="evidence-coverage"><div><b>Applied evidence coverage</b><span>${found.length} / ${skills.length} skills</span></div><div class="evidence-track coverage-track" role="progressbar" aria-label="Applied evidence coverage" aria-valuemin="0" aria-valuemax="${skills.length}" aria-valuenow="${found.length}"><span style="width:${Math.round(found.length/skills.length*100)}%"></span></div></div><div class="evidence-legend"><span class="legend-red">Find evidence</span><span class="legend-amber">Build it</span><span class="legend-green">Show it</span></div><div class="evidence-tree">${skills.map(evidenceNode).join('')}</div><p class="evidence-footnote">Levels describe evidence in your sources, not skill mastery. 0: none · 1: mentioned · 2: learning · 3: applied · 4: applied with a measured outcome. Re-run after updating your sources.</p><div class="hr"></div><h3>Suggested next steps</h3><div class="mini-list">${recommendFromSkills(missing).map(d=>`<div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><span><b>${esc(d.title)}</b><br><span class="footnote">${esc(d.category)}</span></span><button class="btn small primary" data-case="${d.id}">Practice ${ico('arrow',13)}</button></div>`).join('')}</div>`:`<div class="empty" style="padding:25px 12px"><div class="empty-icon">${ico('target',25)}</div><h3>Your next case starts with a goal.</h3><p>Use the sample profile or paste a job description and resume evidence to see your suggested practice topics.</p><div class="note">${ico('shield',15)} Results identify what is written in the resume, not what you are capable of doing.</div></div>`}</div></div>`}
function recommendFromSkills(skills){const txt=skills.map(s=>s.name).join(' ').toLowerCase();let ranked=challenges.map(d=>({...d,_score:d.skills.reduce((a,s)=>a+(txt.includes(s.toLowerCase())?5:0),0)+(txt.includes('sql')&&d.category==='SQL & Data'?6:0)+(txt.includes('experiment')&&d.category==='Experimentation'?6:0)+(txt.includes('python')&&d.category==='Python & Pandas'?6:0)+(txt.includes('marketing')&&d.category==='Marketing'?6:0)+(txt.includes('finance')&&d.category==='Finance & Pricing'?6:0)+(txt.includes('product')&&d.category==='Product Analytics'?6:0)}));return ranked.sort((a,b)=>b._score-a._score).slice(0,3)}
function draft(id){return state.drafts[id]||{answers:['',''],choice:'',reflection:''}}
function resultInfo(d){return state.progress[d.id]||null}
function tableHTML(d){return `<div class="table-scroll"><table class="data-table"><thead><tr>${d.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${d.rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function challengePage(){const d=byId[labId]||challenges[0],a=draft(d.id),r=resultInfo(d);return `<button class="backline" data-page="explore">${ico('chevron',13)} Back to challenge library</button><div class="section-header"><div><div class="eyebrow">INTERACTIVE CASE / ${esc(d.category).toUpperCase()}</div><h1>${esc(d.title)}</h1><div class="focus-list"><span class="tag purple">${esc(d.level)}</span><span class="tag">${ico('clock',12)} ${d.minutes} min</span>${d.skills.slice(0,3).map(s=>`<span class="tag">${esc(s)}</span>`).join('')}${r?.completed?`<span class="tag good">${ico('check',12)} Completed</span>`:''}</div></div><div class="inline-actions"><button class="btn secondary" data-favorite="${d.id}">${ico('heart',15)} ${state.saved.includes(d.id)?'Saved':'Save'}</button><button class="btn secondary" data-action="downloadcsv">${ico('download',16)} Data CSV</button></div></div><div class="lab-layout"><div class="lab-left"><div class="panel panel-pad"><div class="tab-head">${['brief','dataset','coach'].map((v)=>`<button class="${labTab===v?'active':''}" data-labtab="${v}">${{brief:'Case brief',dataset:'Dataset',coach:'AI coach & hints'}[v]}</button>`).join('')}</div>${labTab==='brief'?`<div class="eyebrow">YOUR BUSINESS MISSION</div><h2 style="font:800 22px Manrope;letter-spacing:-.7px">Think like the decision-maker.</h2><p class="text-muted" style="line-height:1.8">${esc(d.brief)}</p><div class="note" style="margin:18px 0">${ico('info',15)} This is a synthetic learning case—not a real company dataset or client engagement.</div><div class="eyebrow">WHAT YOU WILL PRACTICE</div><div class="focus-list">${d.skills.map(s=>`<span class="tag purple">${esc(s)}</span>`).join('')}</div><div class="hr"></div><h3 style="font:800 15px Manrope">Your objective</h3><p class="text-muted smalltext">Use the dataset to calculate the required metrics, make a decision, and explain the risks and assumptions behind your recommendation.</p>`:labTab==='dataset'?`<h2 style="font:800 19px Manrope">Practice dataset</h2><p class="text-muted smalltext">${d.rows.length} records · ${d.columns.length} columns · synthetic data</p>${tableHTML(d)}<div class="inline-actions" style="margin-top:15px"><button class="btn secondary small" data-action="downloadcsv">${ico('download',14)} Download CSV</button><button class="btn outline small" data-action="copycsv">${ico('copy',14)} Copy table</button></div>`:`<h2 style="font:800 19px Manrope">Get unstuck, not given the answer.</h2><p class="text-muted smalltext">Start with a concept hint. If you have connected AI, you can request a personalized next step based on your current work.</p><div class="mini-list" style="margin:15px 0">${d.hints.map((h,i)=>`<div><b>Hint ${i+1}</b><br>${esc(h)}</div>`).join('')}</div><button class="btn primary" data-action="coach" ${loading?'disabled':''}>${ico('spark',16)} Ask my AI coach</button><div id="coach-result" class="feedback-box">${coachResponse?`<div class="note success">${esc(coachResponse)}</div>`:''}</div><p class="footnote" style="margin-top:8px">AI coaching is advisory and may make mistakes. Verify calculations independently.</p>`}</div><div class="panel panel-pad" style="margin-top:18px"><div class="eyebrow">CASE INSIGHT</div><p class="text-muted smalltext">${esc(d.insight)}</p><p class="footnote">The case insight is provided as learning guidance. Full answer keys appear after an attempt.</p></div></div><div class="lab-right"><div class="panel panel-pad"><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px"><div><div class="eyebrow">YOUR WORKSPACE</div><h2 style="font:800 19px Manrope;margin:0">Submit your analysis</h2></div><span class="tag">Autosaved</span></div><div class="note" style="margin-bottom:15px">${ico('shield',15)} Your answers remain in this browser unless you export them. Numeric and multiple-choice checks are automated; written reasoning needs human or AI review.</div><div class="tiny-overline">01 / CALCULATE</div>${d.questions.map((q,i)=>`<div class="question"><label for="q${i}">${i+1}. ${esc(q.label)}</label><div class="answer-row"><input id="q${i}" class="text-input" type="number" step="any" placeholder="Your answer" value="${esc(a.answers[i]??'')}" data-answer="${i}"><span class="unit">${esc(q.unit)}</span></div></div>`).join('')}<div class="tiny-overline" style="margin-top:19px">02 / DECIDE</div><div class="question"><label>${esc(d.choice.prompt)}</label><div class="choice-list">${d.choice.options.map(v=>`<label class="choice-item"><input type="radio" name="case-choice" value="${esc(v)}" ${a.choice===v?'checked':''} data-choice><span>${esc(v)}</span></label>`).join('')}</div></div><div class="tiny-overline" style="margin-top:20px">03 / DEFEND YOUR THINKING</div><div class="form-group" style="margin-top:11px"><label class="field-label" for="reflection">Your recommendation and reasoning</label><textarea class="text-area" id="reflection" style="min-height:155px" placeholder="What do the results mean? What would you recommend, and why? Mention at least one limitation or next step." data-reflection>${esc(a.reflection)}</textarea><div class="field-help">Write your own analysis. This text becomes part of your optional portfolio export.</div></div><div class="inline-actions"><button class="btn primary" data-action="evaluate" ${loading?'disabled':''}>${ico('check',16)} ${loading?'Checking…':'Submit & review'}</button><button class="btn secondary" data-action="clear-draft">Clear draft</button></div>${r?`<div class="hr"></div><div style="display:flex;gap:15px;align-items:center"><div class="score-circle" style="--p:${Math.min(100,r.bestScore||0)}%"><strong>${r.bestScore||0}%</strong></div><div><div class="eyebrow">YOUR BEST PRACTICE CHECK</div><b>${r.completed?'Completed work sample':'Keep practicing'}</b><div class="smalltext text-muted">${r.attempts||1} attempt(s) · ${r.correct||0}/3 structured checks correct</div></div></div><div class="inline-actions" style="margin-top:15px"><button class="btn outline small" data-action="open-results">See detailed review ${ico('arrow',14)}</button>${r.completed?`<button class="btn secondary small" data-action="open-portfolio">View work sample</button>`:''}</div>`:''}</div></div></div>`}
function paperHTML(d,r){const a=r?.submission||draft(d.id);return `<div class="paper" id="print-paper"><div class="tiny-overline">SkillBridge • synthetic practice project</div><h1>${esc(d.title)}</h1><div class="focus-list">${d.skills.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><h2>Business context</h2><p>${esc(d.brief)}</p><h2>My submitted calculations</h2><p>${d.questions.map((q,i)=>`${esc(q.label)}: ${esc(a.answers?.[i]??'Not provided')} ${esc(q.unit)}`).join('\n')}</p><h2>My decision</h2><p>${esc(a.choice||'Not provided')}</p><h2>My analysis & recommendation</h2><p>${esc(a.reflection||'Not submitted')}</p><h2>Practice assessment</h2><p>Structured check: ${Number.isFinite(r?.lastScore)?r.lastScore:0}/100 (numeric and multiple choice; writing completeness only).\n${esc(r?.feedback?.summary||'No validated qualitative score has been assigned.')}</p><h2>Disclosure</h2><p>This is a simulated learning exercise using synthetic data. It is not professional employment, client work, a certification, or an independently verified qualification.</p><p style="font-size:11px;color:var(--muted)">Generated with SkillBridge Studio · ${esc(new Date(r?.completedAt||Date.now()).toLocaleDateString())}</p></div>`}
function portfolio(){let cs=completed().map(r=>({r,d:byId[r.id]})).filter(x=>x.d);return `<div class="section-header"><div><div class="eyebrow">YOUR PROOF OF WORK</div><h1>Practice you can explain.</h1><p class="subtext">A growing collection of real work you've submitted on synthetic cases. Export project drafts—without inventing credentials.</p></div><span class="tag good">${cs.length} work samples</span></div>${cs.length?`<div class="grid g3">${cs.map(({d,r})=>`<div class="panel portfolio-card"><span class="card-symbol">${ico('file',20)}</span><h3>${esc(d.title)}</h3><p>${esc(d.brief)}</p><div class="focus-list">${d.skills.slice(0,2).map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div><footer><span>${r.bestScore}% best structured score</span><button class="section-link" data-portfolio="${d.id}">Open ${ico('arrow',13)}</button></footer></div>`).join('')}</div>`:empty('Your portfolio starts with one decision.','Complete a challenge, submit your own reasoning, and your work sample will appear here.')}<div class="note" style="margin-top:22px">${ico('shield',15)} Portfolio content is a student practice artifact, not a representation of external work or certified performance. You are responsible for reviewing it before sharing.</div>`}
function insights(){const c=completed(),cats=[...new Set(challenges.map(d=>d.category))],theCounts=cats.map(t=>({cat:t,total:challenges.filter(d=>d.category===t).length,n:c.filter(r=>byId[r.id]?.category===t).length})),latest=state.activity.slice(-6).reverse();return `<div class="section-header"><div><div class="eyebrow">YOUR LEARNING ANALYTICS</div><h1>Every project counts.</h1><p class="subtext">Only your own completed work appears here. No fictional streaks, global rankings, or invented performance data.</p></div></div><div class="grid g4">${[['Completed',c.length,'award'],['Attempted',Object.keys(state.progress).length,'book'],['Practice time',totalMinutes()+'m','clock'],['Avg. best score',avgScore()+'%','chart']].map(([l,n,ic])=>`<div class="panel stat"><span class="stat-icon">${ico(ic)}</span><div class="stat-number">${n}</div><div class="stat-caption">${l}</div></div>`).join('')}</div><div class="insight-grid section-space"><div class="panel panel-pad"><h2 class="section-title">Topics covered</h2><p class="smalltext text-muted">Completed cases out of the available challenges</p>${theCounts.map(o=>`<div class="bar-row"><label title="${esc(o.cat)}">${esc(o.cat)}</label><div class="meter"><span style="width:${o.n/o.total*100}%"></span></div><span>${o.n}/${o.total}</span></div>`).join('')}</div><div class="panel panel-pad"><h2 class="section-title">Recent activity</h2><div style="margin-top:12px">${latest.length?latest.map(a=>`<div class="track-item"><span class="track-icon">${ico('check',16)}</span><div class="track-info"><b>${esc(a.title)}</b><small>${esc(new Date(a.at).toLocaleDateString())} · ${esc(a.detail||'')}</small></div></div>`).join(''):`<div class="empty" style="padding:40px 8px">No activity yet. Your first submitted case starts the timeline.</div>`}</div></div></div>`}
function feedbackView(){return `<div class="section-header"><div><div class="eyebrow">VOICE OF THE CUSTOMER</div><h1>Help us build a better SkillBridge.</h1><p class="subtext">Record authentic tester feedback for the USC case competition. Your responses save locally until you export them.</p></div></div><div class="grid g2"><div class="panel panel-pad"><div class="form-group"><label for="f-role" class="field-label">Your relationship to MSBA</label><select id="f-role" style="width:100%"><option>Current USC MSBA student</option><option>Incoming MSBA student</option><option>Other graduate student</option><option>Other tester</option></select></div><div class="form-group"><label for="f-rating" class="field-label">How useful was the product?</label><select id="f-rating" style="width:100%">${[5,4,3,2,1].map(v=>`<option value="${v}">${v} / 5</option>`).join('')}</select></div><div class="form-group"><label for="f-feature" class="field-label">Which feature was most useful?</label><select id="f-feature" style="width:100%"><option>Skill gap scan</option><option>Challenge library</option><option>Automated answer checking</option><option>AI coaching</option><option>Portfolio export</option></select></div><div class="form-group"><label for="f-note" class="field-label">What should we improve?</label><textarea class="text-area" id="f-note" placeholder="Be specific—where did the experience feel confusing, slow, or unhelpful?"></textarea></div><button class="btn primary" data-action="feedback-save">${ico('check',15)} Save tester feedback</button></div><div class="panel panel-pad"><h2 class="section-title">Feedback collection</h2><p class="smalltext text-muted">${state.feedback.length} actual response(s) saved in this browser.</p><div class="note">${ico('info',16)} For competition compliance, speak with real users, analyze their feedback, and implement at least one verifiable product change. An empty local form is not validation.</div><div class="section-separator"></div><div class="inline-actions"><button class="btn secondary" data-action="feedback-export">${ico('download',15)} Export CSV</button></div><div style="margin-top:18px">${state.feedback.slice(-4).reverse().map(o=>`<div class="track-item"><span class="track-icon">${ico('heart',16)}</span><div class="track-info"><b>${esc(o.rating)}/5 · ${esc(o.feature)}</b><small>${esc(o.note)}</small></div></div>`).join('')||'<p class="smalltext text-muted">No results recorded yet.</p>'}</div></div></div>`}
function settingsView(){const st=window.SkillBridgeLocal;return `<div class="section-header"><div><div class="eyebrow">MAKE IT YOUR OWN</div><h1>Preferences & AI setup.</h1><p class="subtext">Control your experience and backups. Keep API keys on the server, never in this browser.</p></div></div><div class="grid g2"><div class="panel panel-pad"><h2 class="section-title">Learner profile</h2><div class="form-group" style="margin-top:19px"><label class="field-label" for="my-name">Display name</label><input class="text-input" id="my-name" maxlength="55" value="${esc(state.name)}"></div><div class="form-group"><label class="field-label" for="my-role">Target role</label><input class="text-input" id="my-role" maxlength="100" value="${esc(state.role)}"></div><button class="btn primary" data-action="profile-save">Save preferences</button><div class="section-separator"></div><h2 class="section-title">Appearance</h2><div class="settings-row"><div><b>Dark mode</b><p>Switch between the light and dark workspace.</p></div><button class="btn secondary" data-action="theme">${ico(state.theme==='dark'?'sun':'moon')} ${state.theme==='dark'?'Use light':'Use dark'}</button></div><div class="section-separator"></div><h2 class="section-title">Your data</h2><div class="settings-row"><div><b>Export your progress</b><p>Download cases, drafts, results, and tester feedback as JSON.</p></div><button class="btn secondary" data-action="backup-export">${ico('download',16)} Export</button></div><div class="settings-row"><div><b>Import a backup</b><p>Replace local records using an exported SkillBridge JSON file.</p></div><label class="btn secondary" for="backup-file">${ico('upload',16)} Import</label><input id="backup-file" type="file" accept="application/json,.json" class="hide"></div><div class="settings-row"><div><b>Reset progress</b><p>Erase drafts, scores, paths, and feedback from this browser.</p></div><button class="btn secondary" data-action="reset">${ico('trash',15)} Reset</button></div></div><div class="panel panel-pad"><h2 class="section-title">Gemini cloud AI</h2><p class="smalltext text-muted">Requires the complete Netlify project and two server-side variables: <span class="inline-code">GEMINI_API_KEY</span> and <span class="inline-code">SKILLBRIDGE_ACCESS_CODE</span>.</p><div class="note ${geminiConnected?'success':''}" style="margin:16px 0">${geminiConnected?'Gemini team access verified for this browser session.':'Gemini '+(cloudConfigured?'backend is configured; enter your team code.':'backend has not been verified on this site.')}</div>${lastError?`<div class="note" role="status">Last AI request: ${esc(lastError)}</div>`:''}<div class="form-group"><label for="team-code" class="field-label">Team access code</label><input class="text-input" id="team-code" type="password" value="" autocomplete="off" placeholder="Enter team-only access code"><p class="field-help">Never paste your Gemini API key here. This shared code is not full user authentication.</p></div><div class="inline-actions"><button class="btn primary" data-action="gemini-connect">${ico('lock',14)} Verify & connect</button><button class="btn secondary" data-action="gemini-status">Check backend</button></div><div class="section-separator"></div><h2 class="section-title">Private on-device AI</h2><p class="smalltext text-muted">Run a small model in your browser when cloud AI is unavailable. Requires desktop WebGPU and may download hundreds of MB or more.</p><div class="inline-actions" style="margin:15px 0"><select id="model-choice" aria-label="Local AI model"><option value="lite">Qwen 0.5B · lighter</option><option value="balanced">Qwen 1.5B · more capable</option></select><button class="btn secondary" data-action="local-load">${ico('download',14)} ${st?.ready()?'Reload local AI':'Load local backup'}</button></div><p id="local-status" class="footnote">${st?.ready()?'Local model loaded':st?.supported()?'Your browser supports WebGPU. Model not loaded.':'This browser or context lacks WebGPU.'}</p><div class="note">Default: Gemini when connected, otherwise an already-loaded local model, then transparent deterministic practice checks. Local model downloads never happen silently.</div></div></div>`}
function render(){updateTheme();let contents={dashboard,explore,paths:pathsView,scan:scanPage,lab:challengePage,portfolio,insights,testing:feedbackView,settings:settingsView};document.getElementById('app').innerHTML=shell((contents[page]||dashboard)());mobileMenu=false}
function nav(p){page=p;mobileMenu=false;coachResponse='';render();window.scrollTo(0,0)}
function openCase(id){if(!byId[id])return;labId=id;page='lab';labTab='brief';coachResponse='';render();window.scrollTo(0,0)}
function dataCSV(d){return [d.columns,...d.rows].map(row=>row.map(x=>{let s=String(x);return /[",\n]/.test(s)?'"'+s.replaceAll('"','""')+'"':s}).join(',')).join('\r\n')+'\r\n'}
function dl(filename,text,mime='text/plain'){const blob=new Blob([text],{type:mime});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}
function addActivity(title,detail){state.activity.push({title,detail,at:new Date().toISOString()});state.activity=state.activity.slice(-80)}
function persistDraft(){const d=byId[labId];if(!d||page!=='lab')return;let a=state.drafts[d.id]||{answers:['',''],choice:'',reflection:''};for(let i=0;i<d.questions.length;i++)a.answers[i]=document.getElementById('q'+i)?.value||'';a.choice=document.querySelector('input[name="case-choice"]:checked')?.value||'';a.reflection=document.getElementById('reflection')?.value||'';state.drafts[d.id]=a;save()}
function evalDraft(d,a){let results=d.questions.map((q,i)=>{const raw=a.answers[i],v=String(raw).trim()===''?NaN:Number(raw),good=Number.isFinite(v)&&Math.abs(v-q.answer)<=q.tolerance;return {label:q.label,answer:q.answer,user:raw,good,explain:q.explain}});const choiceGood=a.choice===d.choice.correct;const reflection=a.reflection.trim();const writingPoints=reflection.length>=120?20:reflection.length>=60?13:reflection.length>=35?7:0;const score=results.filter(q=>q.good).length*30+(choiceGood?20:0)+writingPoints;return {score,correct:results.filter(q=>q.good).length+(choiceGood?1:0),results,choiceGood,writingPoints}}
function resultModal(d,p){const a=p.submission||draft(d.id),r=evalDraft(d,a);return `<div class="modal-head"><div><div class="eyebrow">PRACTICE REVIEW</div><h2>${esc(d.title)}</h2></div><button class="icon-btn" data-close aria-label="Close">${ico('x')}</button></div><div style="display:flex;align-items:center;gap:14px;margin-bottom:16px"><div class="score-circle" style="--p:${r.score}%"><strong>${r.score}%</strong></div><div><b>${r.correct} of 3 structured checks correct</b><p class="smalltext text-muted">Writing completeness: ${r.writingPoints}/20. The score does not validate the quality of your reasoning.</p></div></div><h3>Detailed checks</h3>${r.results.map(q=>`<div class="result-row"><div><strong>${esc(q.label)}</strong><br><span>Yours: ${esc(q.user||'No answer')} · Key: ${q.answer}</span><br><span>${esc(q.explain)}</span></div><span class="${q.good?'goodtext':'badtext'}">${ico(q.good?'check':'x',15)} ${q.good?'Correct':'Review'}</span></div>`).join('')}<div class="result-row"><div><strong>${esc(d.choice.prompt)}</strong><br><span>${esc(d.choice.explain)}</span></div><span class="${r.choiceGood?'goodtext':'badtext'}">${r.choiceGood?'Correct':'Review'}</span></div><div class="note" style="margin:16px 0">${ico('info',16)} <b>Case takeaway:</b> ${esc(d.insight)}</div>${p.feedback?`<div class="note success"><b>${esc(p.feedback.method||'Advisory AI feedback')}</b><p>${esc(p.feedback.summary||'')}</p><b>What worked</b><ul>${(p.feedback.strengths||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ul><b>Improve next</b><ul>${(p.feedback.improvements||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p><b>Next step:</b> ${esc(p.feedback.nextStep||'')}</p></div>`:`<div class="note attention">No qualitative AI evaluation was performed. Numeric checks and written-length points are not a substitute for reviewing reasoning.</div>`}<div class="inline-actions"><button class="btn primary" data-close>Keep practicing ${ico('arrow',14)}</button>${p.completed?`<button class="btn secondary" data-portfolio="${d.id}">View work sample</button>`:''}</div>`}
function openModal(content){modalContent=content;const root=document.getElementById('modal-root');if(root)root.innerHTML=`<div class="modal-backdrop" data-backdrop><div class="modal" role="dialog" aria-modal="true">${content}</div></div>`}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function projectMarkdown(d,p){const a=p.submission||draft(d.id);return `# ${d.title}\n\n> **Synthetic case study / independent practice** · Created with SkillBridge\n\n## Business problem\n${d.brief}\n\n## Dataset\nThis exercise uses a synthetic dataset (${d.rows.length} rows).\n\n## My calculations\n${d.questions.map((q,i)=>`- ${q.label}: ${a.answers?.[i]||'Not provided'} ${q.unit}`).join('\n')}\n\n## My decision\n${a.choice||'Not provided'}\n\n## My analysis and recommendation\n${a.reflection||'Not submitted'}\n\n## Practice check\nStructured score: ${p.lastScore??0}/100 (includes writing-completeness points; **not a skill certification**).\n${p.feedback?.summary||'Written reasoning has not been independently validated.'}\n\n## Disclosure\nThis is a simulated, synthetic training case. Not a real employment or client project. The statements above reflect the learner's own submitted work and may require human verification.\n`}
function openPortfolio(id){const d=byId[id],p=state.progress[id];if(!d||!p)return;openModal(`<div class="modal-head"><div><div class="eyebrow">PORTFOLIO DRAFT</div><h2>Review before sharing</h2></div><button class="icon-btn" data-close>${ico('x')}</button></div>${paperHTML(d,p)}<div class="inline-actions no-print" style="margin-top:18px"><button class="btn primary" data-action="portfolio-download" data-id="${id}">${ico('download',14)} Export Markdown</button><button class="btn secondary" data-action="portfolio-print">${ico('file',14)} Print / Save PDF</button></div>`) }
async function api(kind,payload){const controller=new AbortController(),id=setTimeout(()=>controller.abort(),28000);try{const response=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json','X-SkillBridge-Code':teamCode},body:JSON.stringify({kind,payload}),signal:controller.signal});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`AI request error (${response.status})`);return data}finally{clearTimeout(id)}}
async function hybrid(kind,payload){if(geminiConnected){try{let r=await api(kind,payload);return {...r,method:'Gemini AI'} }catch(e){lastError=e.message;if(kind==='scan'&&payload.documents?.length)return null;toast('Gemini unavailable — trying local AI')}}if(window.SkillBridgeLocal?.ready()){try{let r=await window.SkillBridgeLocal.generate(kind,payload);return {...r,method:'On-device WebLLM'} }catch(e){lastError=e.message;toast('Local AI could not complete this task')}}return null}
function sampleScan(){if(loading||sourceDraft.busy)return;Object.assign(sourceDraft,{linkedinUrl:'',linkedinText:'',profileNotice:'',pdfs:{},useSummary:true});state.role='Product Analyst Intern';state.job='Product Analyst Intern. Work with stakeholders to measure feature performance and conversion funnels. Requirements: SQL, Python, A/B testing, product metrics, dashboards, experiment design, written recommendations.';state.resume='Student analytics projects: SQL queries for customer orders; Python pandas cleaning and visualizations; dashboard tracking monthly revenue. No completed experimental analysis projects are listed.';save();render();toast('Fictional sample profile loaded')}
const keywords=[['SQL',['sql','database','query']],['Python',['python','pandas','numpy']],['A/B testing',['a/b','experiment','randomized']],['Statistics',['statistic','confidence','hypothesis','inference']],['Product metrics',['product','funnel','retention','conversion']],['Visualization',['dashboard','visualization','tableau','power bi']],['Marketing analytics',['marketing','attribution','roas']],['Financial modeling',['financial','pricing','margin','forecast']],['Machine learning',['machine learning','model','classification']],['Operations analytics',['operations','supply chain','inventory']]];
function ruleScan(job,resume){const j=job.toLowerCase(),r=resume.toLowerCase();let skills=keywords.filter(([n,arr])=>arr.some(w=>j.includes(w))).map(([n,arr])=>({name:n,found:arr.some(w=>r.includes(w))&& !(/no completed|no experience|not shown/.test(r)&&n==='A/B testing'),reason:arr.some(w=>r.includes(w))?'Keyword reference found; verify actual experience in the source text.':'No matching term found in the supplied resume.'}));if(!skills.length)skills=keywords.slice(0,5).map(([n])=>({name:n,found:false,reason:'No matching job requirement identified in the keyword demo.'}));return {skills,method:'Keyword demonstration (not AI)'}}
async function runScan(){captureSources();if(sourceDraft.busy)return toast('Wait for the PDF selection to finish.');const job=state.job.trim(),summary=sourceDraft.useSummary?state.resume.trim():'';if(!job)return toast('Add a target job description.');if(job.length>12000||summary.length>16000||sourceDraft.linkedinText.length>16000)return toast('Use up to 12,000 job characters and 16,000 characters per text source.');if(sourceDraft.linkedinUrl.trim()&&!sourceDraft.linkedinText.trim()&&!sourceDraft.pdfs.linkedin)await importProfile();const sources=[summary?{id:'summary',text:summary}:null,sourceDraft.linkedinText.trim()?{id:'linkedin',text:sourceDraft.linkedinText.trim()}:null].filter(Boolean),documents=Object.values(sourceDraft.pdfs).map(({id,name,data})=>({id,name,data}));if(!sources.length&&!documents.length)return toast('Add a summary, resume PDF or readable LinkedIn content.');if(documents.length&&!geminiConnected)return toast('Connect Gemini in Settings to analyze PDF documents.');const resume=sources.map(x=>'['+sourceLabels[x.id]+']\n'+x.text).join('\n\n');save();loading=true;lastError='';render();let result=await hybrid('scan',{job,resume,sources,documents});if(!result?.skills?.length&&documents.length){loading=false;sourceDraft.profileNotice='The PDFs were not reviewed. '+(lastError||'Connect Gemini and retry.');render();return toast('PDF review did not complete; previous results were kept.');}if(!result?.skills?.length)result=ruleScan(job,resume);const skills=result.skills.filter(s=>s&&typeof s.name==='string').slice(0,11).map(s=>({name:String(s.name).slice(0,80),found:s.found===true,evidenceScore:[0,25,50,75,100].includes(s.evidenceScore)?s.evidenceScore:null,reason:String(s.reason||'').slice(0,240),evidence:(Array.isArray(s.evidence)?s.evidence:[]).filter(e=>e&&sourceLabels[e.source]&&typeof e.quote==='string').slice(0,3).map(e=>({source:e.source,quote:e.quote.slice(0,240)}))}));state.scan={skills,method:result.method||'Keyword demonstration (not AI)',date:new Date().toISOString(),reviewedSources:result.reviewedSources||sources.map(s=>s.id),sourceWarnings:result.sourceWarnings||[],inconsistencies:result.inconsistencies||[]};if(sourceDraft.linkedinUrl&&!sources.some(x=>x.id==='linkedin')&&!documents.some(x=>x.id==='linkedin'))state.scan.sourceWarnings.push('The LinkedIn link was not read. Only the other listed sources were reviewed.');save();loading=false;render();toast('Evidence scan completed: '+state.scan.method)}
async function runEvaluation(){persistDraft();const d=byId[labId],a=draft(d.id);if(a.answers.some(v=>String(v).trim()==='')||!a.choice||a.reflection.trim().length<35)return toast('Answer both calculations, choose a decision, and write at least 35 characters of reasoning');const check=evalDraft(d,a);loading=true;render();let feedback=await hybrid('review',{title:d.title,brief:d.brief,columns:d.columns,rows:d.rows,questions:d.questions.map(q=>q.label),student:{answers:a.answers,choice:a.choice,reflection:a.reflection},numericResults:check.results.map(q=>({label:q.label,correct:q.good})),decisionCorrect:check.choiceGood});if(feedback){feedback={summary:String(feedback.summary||'').slice(0,800),strengths:Array.isArray(feedback.strengths)?feedback.strengths.slice(0,4).map(String):[],improvements:Array.isArray(feedback.improvements)?feedback.improvements.slice(0,4).map(String):[],nextStep:String(feedback.nextStep||'').slice(0,450),method:feedback.method}}const old=state.progress[d.id]||{};const wasCompleted=old.completed;const isCompleted=check.correct>=2&&a.reflection.trim().length>=35;state.progress[d.id]={...old,id:d.id,lastScore:check.score,bestScore:Math.max(check.score,old.bestScore||0),correct:check.correct,attempts:(old.attempts||0)+1,completed:wasCompleted||isCompleted,completedAt:new Date().toISOString(),submission:structuredClone(a),feedback};if(isCompleted&&!wasCompleted)addActivity('Completed: '+d.title,`${check.score}/100 practice check`);else addActivity('Attempted: '+d.title,`${check.score}/100 practice check`);save();loading=false;render();openModal(resultModal(d,state.progress[d.id]));toast('Checked answers and saved this attempt')}
async function askCoach(){const d=byId[labId];persistDraft();loading=true;render();const a=draft(d.id),hint=await hybrid('coach',{case:d.title,brief:d.brief,rows:d.rows,questionLabels:d.questions.map(q=>q.label),myWork:{answers:a.answers,reflection:a.reflection.slice(0,1000)}});coachResponse=hint?.hint?`${hint.concept?hint.concept+': ':''}${hint.hint}`:d.hints[0]+' (curated hint — not AI)';loading=false;render();toast(hint?.method||'Curated hint shown')}
async function statusCheck(show=false){try{let r=await fetch('/api/status',{cache:'no-store'});const data=await r.json();cloudConfigured=!!data.configured;if(show)toast(cloudConfigured?'Backend ready. Enter your access code to connect.':'Backend not configured. Check environment variables and functions.');return cloudConfigured}catch{cloudConfigured=false;if(show)toast('No Netlify AI backend detected on this address.');return false}}
async function connectGemini(){teamCode=document.getElementById('team-code')?.value.trim()||'';if(!teamCode)return toast('Enter your team access code');try{const r=await api('verify',{});geminiConnected=r.ok===true;toast(geminiConnected?'Gemini backend connected successfully':'Connection not verified');render()}catch(e){geminiConnected=false;lastError=e.message;toast('Could not connect: '+e.message)}}
async function loadLocal(){if(!window.SkillBridgeLocal?.supported())return toast('WebGPU and HTTPS are required for on-device AI');const choose=document.getElementById('model-choice')?.value||'lite';const output=document.getElementById('local-status');if(!window.confirm('Download an AI model to this browser? This can require hundreds of MB or more and uses your GPU.'))return;try{await window.SkillBridgeLocal.load(choose,msg=>{if(output)output.textContent=msg});render();toast('On-device AI ready. Cloud fallback is now available.')}catch(e){if(output)output.textContent=e.message;toast('Unable to load local model: '+e.message)}}
function feedbackSave(){const note=document.getElementById('f-note')?.value.trim();if(!note||note.length<8)return toast('Please add specific, genuine feedback (at least 8 characters)');const item={role:document.getElementById('f-role').value,rating:Number(document.getElementById('f-rating').value),feature:document.getElementById('f-feature').value,note:note.slice(0,2000),at:new Date().toISOString()};state.feedback.push(item);save();render();toast('Tester feedback saved locally — remember to export it')}
function feedbackCSV(){const h=['date','role','rating','feature','note'];return [h,...state.feedback.map(x=>[x.at,x.role,x.rating,x.feature,x.note])].map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n')}
function applyInput(e){const el=e.target;if(page==='scan'){captureSources();updateSourceMeter();}if(e.type==='change'&&el.id==='case-search')return;if(page==='lab'&&(el.matches('[data-answer]')||el.matches('[data-choice]')||el.matches('[data-reflection]')))persistDraft();if(el.id==='case-search'){search=el.value;document.getElementById('explore-grid').innerHTML=exploreGrid()}if(el.id==='case-level'){difficulty=el.value;document.getElementById('explore-grid').innerHTML=exploreGrid()}}
async function click(e){captureSources();const el=e.target.closest('button,[data-portfolio],[data-case],[data-favorite],[data-path],[data-topic],[data-labtab],[data-close],[data-action]');if(!el)return;if(el.hasAttribute('data-close'))return closeModal();if(el.dataset.page)return nav(el.dataset.page);if(el.dataset.case)return openCase(el.dataset.case);if(el.dataset.portfolio)return openPortfolio(el.dataset.portfolio);if(el.dataset.favorite){const id=el.dataset.favorite;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render();return toast(state.saved.includes(id)?'Case bookmarked':'Bookmark removed')}if(el.dataset.path){state.path=el.dataset.path;save();render();document.getElementById('path-detail')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(el.dataset.topic){topic=el.dataset.topic;page='explore';render();window.scrollTo(0,0);return}if(el.dataset.labtab){persistDraft();labTab=el.dataset.labtab;render();return}switch(el.dataset.action){case 'remove-pdf':delete sourceDraft.pdfs[el.dataset.source];render();break;case 'import-linkedin':await importProfile();break;case 'menu':mobileMenu=!mobileMenu;render();break;case 'theme':state.theme=state.theme==='dark'?'light':'dark';save();render();break;case 'quicksearch':nav('explore');setTimeout(()=>document.getElementById('case-search')?.focus(),50);break;case 'clearfilters':topic='All topics';difficulty='Any level';search='';render();break;case 'sample-scan':sampleScan();break;case 'scan':await runScan();break;case 'downloadcsv':dl(`skillbridge_${labId}_synthetic.csv`,dataCSV(byId[labId]),'text/csv');toast('Synthetic practice CSV downloaded');break;case 'copycsv':await navigator.clipboard.writeText(dataCSV(byId[labId])).then(()=>toast('Dataset copied')).catch(()=>toast('Copy not supported'));break;case 'evaluate':await runEvaluation();break;case 'open-results':{const d=byId[labId];openModal(resultModal(d,state.progress[d.id]));break}case 'open-portfolio':openPortfolio(labId);break;case 'clear-draft':if(!window.confirm('Clear your unsent draft for this case? Saved attempts are kept.'))break;state.drafts[labId]={answers:['',''],choice:'',reflection:''};save();render();break;case 'coach':await askCoach();break;case 'gemini-status':await statusCheck(true);render();break;case 'gemini-connect':await connectGemini();break;case 'local-load':await loadLocal();break;case 'profile-save':state.name=document.getElementById('my-name').value.trim().slice(0,55)||'Guest learner';state.role=document.getElementById('my-role').value.trim().slice(0,100)||'Analyst';save();render();toast('Preferences updated');break;case 'portfolio-download':{const id=el.dataset.id,d=byId[id],p=state.progress[id];if(d&&p)dl(`skillbridge_${id}_practice_case.md`,projectMarkdown(d,p),'text/markdown');break}case 'portfolio-print':window.print();break;case 'feedback-save':feedbackSave();break;case 'feedback-export':if(!state.feedback.length){toast('No tester feedback to export yet');break}dl('skillbridge_real_tester_feedback.csv',feedbackCSV(),'text/csv');break;case 'backup-export':dl('skillbridge_progress_backup.json',JSON.stringify({version:1,exported:new Date().toISOString(),state},null,2),'application/json');break;case 'reset':if(!window.confirm('Erase all local progress, case drafts, survey feedback, and portfolio records? This cannot be undone without a backup.'))break;localStorage.removeItem(SKEY);location.reload();break;}}
document.addEventListener('change',async e=>{if(e.target?.id==='resumePdf-file')await selectPdf('resumePdf',e.target.files[0]);if(e.target?.id==='linkedin-file')await selectPdf('linkedin',e.target.files[0]);});
document.addEventListener('click',click);document.addEventListener('input',applyInput);document.addEventListener('change',applyInput);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='/'&&!/input|textarea/i.test(document.activeElement.tagName)){e.preventDefault();nav('explore');document.getElementById('case-search')?.focus()}});document.addEventListener('change',async e=>{if(e.target?.id!=='backup-file')return;const f=e.target.files[0];if(!f)return;try{let json=JSON.parse(await f.text());if(!json.state||typeof json.state!=='object'||Array.isArray(json.state)||Object.keys(json.state.progress||{}).length>300)return toast('Not a valid SkillBridge backup');if(!window.confirm('Replace current browser records with this backup?'))return;state={...state,...json.state};save();render();toast('Backup restored')}catch{toast('Cannot read this backup file')}});
render();statusCheck(false);
})();

